def solve(grid, M, N):
     row_max = {}
     column_max = {}
     for i in range(M):
         row_max[i] = max(grid[i])
     for i in range(N):
         column_max[i] = max([grid[j][i] for j in range(M)])
     for i in range(M):
         for j in range(N):
             v = grid[i][j]
             if v < row_max[i] and v < column_max[j]:
                 return "NO"
     return "YES"

