 		for case_index, case in iterate_cases_1lpc(filepath):

 			print "case #%d: time:%.02f" % (case_index, time.time() - start_time)
 			result = calc_result(case)

 			#######################
 			#### format output ####
 			#######################
 			f_out.write("Case #%d: %s\n" % (case_index, result))

