 def read_floats(): return map(float, stdin.readline().split())


 def solve_case():
     C, F, X = read_floats()
     rate = 2
     current = 0
     best = X / rate

     while True:
         current += C / rate
         rate += F
         next = current + X / rate
         if next < best:
             best = next
         else:
             break

     return best


