 board = []

 def whoIsWinner(num):
     if num == 4000 or num == 3010:
         return 'X'
     if num == 400 or num == 310:
         return 'O'
     return False

 def process(board):
     full = True
     newboard = []
     for i in range(4):
         line = []
         for j in range(4):
             c = board[i][j]
             if   c == 'X':
                 line.append(1000)
             elif c == 'O':
                 line.append(100)
             elif c == 'T':
                 line.append(10)
             elif c == '.':
                 line.append(1)
                 full = False
         newboard.append(line)
     board = newboard
     for i in range(4):
         sumH = 0
         sumV = 0
         for j in range(4):
             sumH += board[i][j]
             sumV += board[j][i]
         winner = whoIsWinner(sumH)
         if winner:
             return winner + ' won'
         winner = whoIsWinner(sumV)
         if winner:
             return winner + ' won'
     sumD0 = board[0][0] + board[1][1] + board[2][2] + board[3][3]
     winner = whoIsWinner(sumD0)
     if winner:
         return winner + ' won'
     sumD1 = board[3][0] + board[2][1] + board[1][2] + board[0][3]
     winner = whoIsWinner(sumD1)
     if winner:
         return winner + ' won'
     if full:
         return 'Draw'
     return 'Game has not completed'

