def PlayDevious(list1, list2):
     Ret = 0;
     i = 0;
     j = 0;
     while (i < len(list1)):
         if list1[i] > list2[j]:
             j += 1;
         i += 1;
     return j;

 def PlayWar(list1, list2):
     j = 0;      Score = 0;
     for entry in list1:
         winner = False;
         while (not winner):
             if j != len(list2):
                 if list2[j] > entry:
                     winner = True;
                 j += 1;
             else:
                 Score += 1;
                 winner = True;

     return Score;

 def PlayWar2(list1, list2):
     L1 = [];        L2 = [];        Score = 0;

     for i in range(len(list1)):
         L1.append(list1[i]);        L2.append(list2[i]);
     L1.reverse();

     Score = 0;
     for play in L1:
         index =  0;
         for i in range(1, len(L2)):
             if L2[i] > play > L2[i-1]:
                 index = i;

         if play > L2[index]:
             Score += 1;
         L2.pop(index);
     return Score           


