     if(lan.get(s2[i])==None and s2[i]!=" "):
         lan[s2[i]]=e2[i]
     if(lan.get(s3[i])==None and s3[i]!=" "):
         lan[s3[i]]=e3[i]

 f = open("A-small-attempt0.in", "r")
 n=int(f.readline().strip())
 for i  in xrange(n):
     line=f.readline().strip()
     res='Case #'+str((i+1))+": "
